@Override
    protected boolean canTrack(@Nullable LivingEntity target, TargetPredicate targetPredicate) {
        return super.canTrack(target, targetPredicate) && !(target instanceof IronGolemEntity) && !(target instanceof GuardEntity);
    }

@Override
    public void start() {
        this.mob.setTarget(this.attacker);
        LivingEntity livingentity = this.guard.getOwner();
        if (livingentity != null) {
            this.timestamp = livingentity.getLastAttackedTime();
        }

        super.start();
    }

public static void handle(GuardFollowPacket guardFollowPacket, ServerPlayerEntity serverPlayerEntity, PacketSender packetSender) {
        int entityId = guardFollowPacket.id;

        Entity entity = serverPlayerEntity.getWorld().getEntityById(entityId);
        if (entity instanceof GuardEntity guardEntity) {
            guardEntity.setFollowing(!guardEntity.isFollowing());
            guardEntity.setOwnerId(serverPlayerEntity.getUuid());
            guardEntity.playSound(SoundEvents.ENTITY_VILLAGER_YES, 1, 1);
        }
    }

public static GuardFollowPacket read(PacketByteBuf buf) {
        int id = buf.readInt();
        return new GuardFollowPacket(id);
    }

@Override
    public void write(PacketByteBuf buf) {
        buf.writeInt(id);
    }

@Override
    public PacketType<?> getType() {
        return PACKET_TYPE;
    }

public static void handle(GuardPatrolPacket packet, ServerPlayerEntity serverPlayerEntity, PacketSender buf) {
        int entityId = packet.id;
        boolean pressed = packet.pressed;

        Entity entity = serverPlayerEntity.getWorld().getEntityById(entityId);
        if (entity instanceof GuardEntity guardEntity) {
            BlockPos pos = guardEntity.getBlockPos();
            if (guardEntity.getBlockPos() != null) {
                guardEntity.setPatrolPos(pos);
            }
            guardEntity.setPatrolling(pressed);
        }
    }

private static GuardPatrolPacket read(PacketByteBuf buf) {
        int id = buf.readInt();
        boolean pressed = buf.readBoolean();
        return new GuardPatrolPacket(id, pressed);
    }

@Override
    public void write(PacketByteBuf buf) {
        buf.writeInt(id);
        buf.writeBoolean(pressed);
    }

@Override
    public PacketType<?> getType() {
        return PACKET_TYPE;
    }
